// AgentStateServiceClient is the client API for AgentStateService service.
//
// For semantics around ctx use and closing/ending streaming RPCs, please refer to https://pkg.go.dev/google.golang.org/grpc/?tab=doc#ClientConn.NewStream.
//
// Client-facing gateway service for agent state operations.
// The gateway generates execution plans locally and routes to data nodes.
type AgentStateServiceClient interface {
	// ── Branch (fork) operations ─────────────────────────────────────────
	Fork(ctx context.Context, in *AgentForkRequest, opts ...grpc.CallOption) (*AgentForkResponse, error)
	MergeBranch(ctx context.Context, in *AgentMergeBranchRequest, opts ...grpc.CallOption) (*AgentMergeBranchResponse, error)
	DiscardBranch(ctx context.Context, in *AgentDiscardBranchRequest, opts ...grpc.CallOption) (*AgentDiscardBranchResponse, error)
	ListBranches(ctx context.Context, in *AgentListBranchesRequest, opts ...grpc.CallOption) (*AgentListBranchesResponse, error)
	BranchPut(ctx context.Context, in *AgentBranchPutRequest, opts ...grpc.CallOption) (*AgentBranchPutResponse, error)
	BranchGet(ctx context.Context, in *AgentBranchGetRequest, opts ...grpc.CallOption) (*AgentBranchGetResponse, error)
	// ── Causal graph operations ──────────────────────────────────────────
	AddStep(ctx context.Context, in *AgentAddStepRequest, opts ...grpc.CallOption) (*AgentAddStepResponse, error)
	AddEdge(ctx context.Context, in *AgentAddEdgeRequest, opts ...grpc.CallOption) (*AgentAddEdgeResponse, error)
	GetStep(ctx context.Context, in *AgentGetStepRequest, opts ...grpc.CallOption) (*AgentGetStepResponse, error)
	GetContent(ctx context.Context, in *AgentGetContentRequest, opts ...grpc.CallOption) (*AgentGetContentResponse, error)
	GetEdges(ctx context.Context, in *AgentGetEdgesRequest, opts ...grpc.CallOption) (*AgentGetEdgesResponse, error)
	Traverse(ctx context.Context, in *AgentTraverseRequest, opts ...grpc.CallOption) (*AgentTraverseResponse, error)
	FindSimilarChains(ctx context.Context, in *AgentFindSimilarChainsRequest, opts ...grpc.CallOption) (*AgentFindSimilarChainsResponse, error)
	// ── Reactive state operations ────────────────────────────────────────
	CasPut(ctx context.Context, in *AgentCasPutRequest, opts ...grpc.CallOption) (*AgentCasPutResponse, error)
	TxnCommit(ctx context.Context, in *AgentTxnCommitRequest, opts ...grpc.CallOption) (*AgentTxnCommitResponse, error)
	// ── Coordination primitives (claim / lease / renew / release) ─────────
	// Native etcd/Consul/Zookeeper-style coordination: a claim is an atomic
	// SetIfNotExists(claim_key, agent_id); a lease is the same with a TTL so an
	// un-renewed holder auto-expires; renew/release are fenced so only the live
	// holder can extend/drop the key. See issue #691.
	Claim(ctx context.Context, in *AgentClaimRequest, opts ...grpc.CallOption) (*AgentClaimResponse, error)
	Lease(ctx context.Context, in *AgentLeaseRequest, opts ...grpc.CallOption) (*AgentLeaseResponse, error)
	Renew(ctx context.Context, in *AgentRenewRequest, opts ...grpc.CallOption) (*AgentRenewResponse, error)
	Release(ctx context.Context, in *AgentReleaseRequest, opts ...grpc.CallOption) (*AgentReleaseResponse, error)
	// ── Temporal graph operations ────────────────────────────────────────
	ExpireEdge(ctx context.Context, in *AgentExpireEdgeRequest, opts ...grpc.CallOption) (*AgentExpireEdgeResponse, error)
	EdgeHistory(ctx context.Context, in *AgentEdgeHistoryRequest, opts ...grpc.CallOption) (*AgentEdgeHistoryResponse, error)
	// ── Memory-scope provenance audit (#697 phase 4) ──────────────────────
	// Gated by ManageMemoryScope; the gateway authorizes then forwards to the
	// data node that owns the `_agent_provenance` CF.
	QueryProvenance(ctx context.Context, in *AgentQueryProvenanceRequest, opts ...grpc.CallOption) (*AgentQueryProvenanceResponse, error)
	// ── Memory-scope team-membership admin (#697 phase 2c / #794) ─────────
	// Grant/revoke an agent's team membership; gated by ManageMemoryScope. The
	// gateway authorizes then applies a durable metadata-Raft op so the change
	// immediately affects Team-scope reads after the next internal-token refresh.
	AgentManageTeamGrant(ctx context.Context, in *AgentManageTeamGrantRequest, opts ...grpc.CallOption) (*AgentManageTeamGrantResponse, error)
	// ── Team time-travel (#787) — gateway facade fan-out/fence/merge ──────
	AgentTeamSnapshotLocal(ctx context.Context, in *TeamSnapshotLocalRequest, opts ...grpc.CallOption) (*TeamSnapshotLocalResponse, error)
	AgentTeamDiffLocal(ctx context.Context, in *TeamDiffLocalRequest, opts ...grpc.CallOption) (*TeamDiffLocalResponse, error)
	// Cascade-expire a fact and its derived dependents (#693).
	CascadeExpire(ctx context.Context, in *AgentCascadeExpireRequest, opts ...grpc.CallOption) (*AgentCascadeExpireResponse, error)
	// Supersede a fact with a replacement, optionally cascading (#693 phase 4).
	SupersedeFact(ctx context.Context, in *AgentSupersedeFactRequest, opts ...grpc.CallOption) (*AgentSupersedeFactResponse, error)
	// Transactional memory ingest (#780): forwarded to the owning data node's
	// AgentMemoryIngest (atomic, snapshot-isolated dedup/create/supersede).
	MemoryIngest(ctx context.Context, in *AgentMemoryIngestRequest, opts ...grpc.CallOption) (*AgentMemoryIngestResponse, error)
	// ── Bitemporal belief queries ("who believed what, when") ─────────────
	BeliefQuery(ctx context.Context, in *AgentBeliefQueryRequest, opts ...grpc.CallOption) (*AgentBeliefQueryResponse, error)
	BeliefDivergence(ctx context.Context, in *AgentBeliefDivergenceRequest, opts ...grpc.CallOption) (*AgentBeliefDivergenceResponse, error)
	// ── Durable agent execution (#846, epic #699 / sub-epic #792) ─────────
	// Run-id-pinned routing: StartRun picks a shard by hashing run_key/agent_id
	// through the ShardRouter and returns run_id = (shard_id << 40) | local_seq;
	// every subsequent call extracts the owning shard as run_id >> 40 — no
	// metadata lookup needed to route. The gateway resolves that shard's leader
	// and retries on NotLeader.
	StartRun(ctx context.Context, in *AgentStartRunRequest, opts ...grpc.CallOption) (*AgentStartRunResponse, error)
	RunStep(ctx context.Context, in *AgentRunStepRequest, opts ...grpc.CallOption) (*AgentRunStepResponse, error)
	CompleteStep(ctx context.Context, in *AgentCompleteStepRequest, opts ...grpc.CallOption) (*AgentCompleteStepResponse, error)
	CheckpointGet(ctx context.Context, in *AgentCheckpointGetRequest, opts ...grpc.CallOption) (*AgentCheckpointGetResponse, error)
	CheckpointLatest(ctx context.Context, in *AgentCheckpointLatestRequest, opts ...grpc.CallOption) (*AgentCheckpointLatestResponse, error)
	ProvenanceChainQuery(ctx context.Context, in *AgentProvenanceChainQueryRequest, opts ...grpc.CallOption) (*AgentProvenanceChainQueryResponse, error)
	ResumeFromStep(ctx context.Context, in *AgentResumeFromStepRequest, opts ...grpc.CallOption) (*AgentResumeFromStepResponse, error)
	ResumeSemantic(ctx context.Context, in *AgentResumeSemanticRequest, opts ...grpc.CallOption) (*AgentResumeSemanticResponse, error)
	GetRunStatus(ctx context.Context, in *AgentGetRunStatusRequest, opts ...grpc.CallOption) (*AgentGetRunStatusResponse, error)
	// Phase 5 (#797): branch/time-travel resume. Routed by source_run_id >> 40 to
	// the shard owning the source run; the child run is allocated on that same
	// shard so its self-routing run_id stays addressable.
	ForkRun(ctx context.Context, in *AgentForkRunRequest, opts ...grpc.CallOption) (*AgentForkRunResponse, error)
	ForkAcrossCandidates(ctx context.Context, in *AgentForkAcrossCandidatesRequest, opts ...grpc.CallOption) (*AgentForkAcrossCandidatesResponse, error)
	ArtifactPut(ctx context.Context, in *AgentArtifactPutRequest, opts ...grpc.CallOption) (*AgentArtifactPutResponse, error)
	ArtifactGet(ctx context.Context, in *AgentArtifactGetRequest, opts ...grpc.CallOption) (*AgentArtifactGetResponse, error)
	ArtifactResolve(ctx context.Context, in *AgentArtifactResolveRequest, opts ...grpc.CallOption) (*AgentArtifactResolveResponse, error)
	// ── Streaming ops ────────────────────────────────────────────────────
	WatchPrefix(ctx context.Context, in *AgentWatchPrefixRequest, opts ...grpc.CallOption) (grpc.ServerStreamingClient[AgentWatchEventProto], error)
}

