// AgentStateServiceServer is the server API for AgentStateService service.
// All implementations must embed UnimplementedAgentStateServiceServer
// for forward compatibility.
//
// Client-facing gateway service for agent state operations.
// The gateway generates execution plans locally and routes to data nodes.
type AgentStateServiceServer interface {
	// ── Branch (fork) operations ─────────────────────────────────────────
	Fork(context.Context, *AgentForkRequest) (*AgentForkResponse, error)
	MergeBranch(context.Context, *AgentMergeBranchRequest) (*AgentMergeBranchResponse, error)
	DiscardBranch(context.Context, *AgentDiscardBranchRequest) (*AgentDiscardBranchResponse, error)
	ListBranches(context.Context, *AgentListBranchesRequest) (*AgentListBranchesResponse, error)
	BranchPut(context.Context, *AgentBranchPutRequest) (*AgentBranchPutResponse, error)
	BranchGet(context.Context, *AgentBranchGetRequest) (*AgentBranchGetResponse, error)
	// ── Causal graph operations ──────────────────────────────────────────
	AddStep(context.Context, *AgentAddStepRequest) (*AgentAddStepResponse, error)
	AddEdge(context.Context, *AgentAddEdgeRequest) (*AgentAddEdgeResponse, error)
	GetStep(context.Context, *AgentGetStepRequest) (*AgentGetStepResponse, error)
	GetContent(context.Context, *AgentGetContentRequest) (*AgentGetContentResponse, error)
	GetEdges(context.Context, *AgentGetEdgesRequest) (*AgentGetEdgesResponse, error)
	Traverse(context.Context, *AgentTraverseRequest) (*AgentTraverseResponse, error)
	FindSimilarChains(context.Context, *AgentFindSimilarChainsRequest) (*AgentFindSimilarChainsResponse, error)
	// ── Reactive state operations ────────────────────────────────────────
	CasPut(context.Context, *AgentCasPutRequest) (*AgentCasPutResponse, error)
	TxnCommit(context.Context, *AgentTxnCommitRequest) (*AgentTxnCommitResponse, error)
	// ── Coordination primitives (claim / lease / renew / release) ─────────
	// Native etcd/Consul/Zookeeper-style coordination: a claim is an atomic
	// SetIfNotExists(claim_key, agent_id); a lease is the same with a TTL so an
	// un-renewed holder auto-expires; renew/release are fenced so only the live
	// holder can extend/drop the key. See issue #691.
	Claim(context.Context, *AgentClaimRequest) (*AgentClaimResponse, error)
	Lease(context.Context, *AgentLeaseRequest) (*AgentLeaseResponse, error)
	Renew(context.Context, *AgentRenewRequest) (*AgentRenewResponse, error)
	Release(context.Context, *AgentReleaseRequest) (*AgentReleaseResponse, error)
	// ── Temporal graph operations ────────────────────────────────────────
	ExpireEdge(context.Context, *AgentExpireEdgeRequest) (*AgentExpireEdgeResponse, error)
	EdgeHistory(context.Context, *AgentEdgeHistoryRequest) (*AgentEdgeHistoryResponse, error)
	// ── Memory-scope provenance audit (#697 phase 4) ──────────────────────
	// Gated by ManageMemoryScope; the gateway authorizes then forwards to the
	// data node that owns the `_agent_provenance` CF.
	QueryProvenance(context.Context, *AgentQueryProvenanceRequest) (*AgentQueryProvenanceResponse, error)
	// ── Memory-scope team-membership admin (#697 phase 2c / #794) ─────────
	// Grant/revoke an agent's team membership; gated by ManageMemoryScope. The
	// gateway authorizes then applies a durable metadata-Raft op so the change
	// immediately affects Team-scope reads after the next internal-token refresh.
	AgentManageTeamGrant(context.Context, *AgentManageTeamGrantRequest) (*AgentManageTeamGrantResponse, error)
	// ── Team time-travel (#787) — gateway facade fan-out/fence/merge ──────
	AgentTeamSnapshotLocal(context.Context, *TeamSnapshotLocalRequest) (*TeamSnapshotLocalResponse, error)
	AgentTeamDiffLocal(context.Context, *TeamDiffLocalRequest) (*TeamDiffLocalResponse, error)
	// Cascade-expire a fact and its derived dependents (#693).
	CascadeExpire(context.Context, *AgentCascadeExpireRequest) (*AgentCascadeExpireResponse, error)
	// Supersede a fact with a replacement, optionally cascading (#693 phase 4).
	SupersedeFact(context.Context, *AgentSupersedeFactRequest) (*AgentSupersedeFactResponse, error)
	// Transactional memory ingest (#780): forwarded to the owning data node's
	// AgentMemoryIngest (atomic, snapshot-isolated dedup/create/supersede).
	MemoryIngest(context.Context, *AgentMemoryIngestRequest) (*AgentMemoryIngestResponse, error)
	// ── Bitemporal belief queries ("who believed what, when") ─────────────
	BeliefQuery(context.Context, *AgentBeliefQueryRequest) (*AgentBeliefQueryResponse, error)
	BeliefDivergence(context.Context, *AgentBeliefDivergenceRequest) (*AgentBeliefDivergenceResponse, error)
	// ── Durable agent execution (#846, epic #699 / sub-epic #792) ─────────
	// Run-id-pinned routing: StartRun picks a shard by hashing run_key/agent_id
	// through the ShardRouter and returns run_id = (shard_id << 40) | local_seq;
	// every subsequent call extracts the owning shard as run_id >> 40 — no
	// metadata lookup needed to route. The gateway resolves that shard's leader
	// and retries on NotLeader.
	StartRun(context.Context, *AgentStartRunRequest) (*AgentStartRunResponse, error)
	RunStep(context.Context, *AgentRunStepRequest) (*AgentRunStepResponse, error)
	CompleteStep(context.Context, *AgentCompleteStepRequest) (*AgentCompleteStepResponse, error)
	CheckpointGet(context.Context, *AgentCheckpointGetRequest) (*AgentCheckpointGetResponse, error)
	CheckpointLatest(context.Context, *AgentCheckpointLatestRequest) (*AgentCheckpointLatestResponse, error)
	ProvenanceChainQuery(context.Context, *AgentProvenanceChainQueryRequest) (*AgentProvenanceChainQueryResponse, error)
	ResumeFromStep(context.Context, *AgentResumeFromStepRequest) (*AgentResumeFromStepResponse, error)
	ResumeSemantic(context.Context, *AgentResumeSemanticRequest) (*AgentResumeSemanticResponse, error)
	GetRunStatus(context.Context, *AgentGetRunStatusRequest) (*AgentGetRunStatusResponse, error)
	// Phase 5 (#797): branch/time-travel resume. Routed by source_run_id >> 40 to
	// the shard owning the source run; the child run is allocated on that same
	// shard so its self-routing run_id stays addressable.
	ForkRun(context.Context, *AgentForkRunRequest) (*AgentForkRunResponse, error)
	ForkAcrossCandidates(context.Context, *AgentForkAcrossCandidatesRequest) (*AgentForkAcrossCandidatesResponse, error)
	ArtifactPut(context.Context, *AgentArtifactPutRequest) (*AgentArtifactPutResponse, error)
	ArtifactGet(context.Context, *AgentArtifactGetRequest) (*AgentArtifactGetResponse, error)
	ArtifactResolve(context.Context, *AgentArtifactResolveRequest) (*AgentArtifactResolveResponse, error)
	// ── Streaming ops ────────────────────────────────────────────────────
	WatchPrefix(*AgentWatchPrefixRequest, grpc.ServerStreamingServer[AgentWatchEventProto]) error
	mustEmbedUnimplementedAgentStateServiceServer()
}

